const MENTOR_SPIRIT_DESCRIPTIONS: Record<string, string> = {
  bear: 'A protective healer who fights ferociously, even recklessly, for those in his care. Grants resistance-test bonuses, help with health magic or Rapid Healing, but risks going berserk when you or a ward is hurt.',
  cat: 'Stealthy, sly, and arrogant, toying with prey rather than striking cleanly. Grants Gymnastics/Infiltration or illusion-magic bonuses and Light Body, but you can’t finish a fight quickly unless you rein in the theatrics.',
  dog: 'A loyal, stubborn protector who tracks threats and never abandons a friend. Grants Tracking and detection-magic bonuses and sharpened senses, but you can’t leave a comrade behind without a fight.',
  dragonslayer: 'A heroic, fun-loving warrior who keeps every oath. Grants a social-skill bonus, combat-magic bonuses, and better aim and reflexes, but breaking a promise costs you dice until you make it right.',
  eagle: 'A proud, solitary guardian of nature’s purity, distrustful of technology and pollution. Grants Perception and air-spirit bonuses and sharper combat instincts, but leaves you allergic to pollutants.',
  'fire-bringer': 'A kind creator who devotes himself to others, sometimes to his own detriment. Grants Artisan/Alchemy or manipulation-magic bonuses and skill growth, but you can’t refuse a sincere request for help.',
  mountain: 'Rooted, stubborn, and nearly unmovable once a decision is made. Grants Survival and defensive-magic bonuses and extra magical armor, but changing your plan (or acting without one) takes real effort.',
  rat: 'A resourceful survivor who avoids open fights and strikes fast when cornered. Grants Sneaking and reagent-harvesting bonuses and toxin resistance, but pushes you to flee or hide first in a fight.',
  raven: 'A dark trickster who profits from chaos without causing it. Grants Con and manipulation-magic bonuses, stealth, and voice tricks, but tempts you toward exploiting others’ misfortune or pulling pranks.',
  sea: 'Unfathomable and moody — comforting one moment, dangerous the next, and fiercely protective of what she’s given. Grants Swimming and water-spirit bonuses and athletic boosts, but makes you reluctant to give anything away.',
  seducer: 'The incarnation of desire, exploiting weakness and inflaming others’ wants from a safe distance. Grants Con and illusion-magic bonuses and social skill tricks, but you struggle to resist temptation when it’s offered.',
  shark: 'A cold, relentless, wandering hunter who strikes without warning. Grants Unarmed Combat and combat-magic bonuses and a free lethal unarmed strike, but risks going berserk once blood is drawn.',
  snake: 'Wise and secretive, trading knowledge for a price and fighting only when needed. Grants Arcana and detection-magic bonuses and sharper social reads, but you can’t resist chasing a hint of hidden knowledge.',
  thunderbird: 'A primal, majestic storm made flesh, respected and feared in equal measure. Grants Intimidation and air-spirit bonuses and harder-hitting strikes, but you can’t let an insult go unanswered.',
  'wise-warrior': 'A disciplined tactician who fights from wisdom rather than bloodlust, bound by a warrior’s code. Grants Leadership/Instruction and combat-magic bonuses and sharper skill, but dishonorable behavior costs you dice until atoned for.',
  wolf: 'A loyal pack hunter, devoted to friends and family to the last. Grants Tracking and combat-magic bonuses and faster reflexes, but you can’t bring yourself to retreat from a fight.',
}

