function lookup(dictionary: Record<string, string>, id: string, fallback: string): string {
  return dictionary[id] ?? fallback
}

export function describeAttribute(id: string): string {
  return lookup(ATTRIBUTE_DESCRIPTIONS, id, 'A core attribute used to build dice pools for related tests.')
}

export function describeQuality(id: string): string {
  return lookup(QUALITY_DESCRIPTIONS, id, 'A creation-time quality with a fixed Karma cost.')
}

export function describePath(kind: string): string {
  return lookup(PATH_DESCRIPTIONS, kind, 'An awakened or resonant path with its own grants and restrictions.')
}

export function describeTradition(id: string): string {
  return lookup(TRADITION_DESCRIPTIONS, id, 'A magical tradition setting the drain attribute and allowed spirit list.')
}

export function describeAspectedValue(id: string): string {
  return lookup(ASPECTED_VALUE_DESCRIPTIONS, id, 'The single magical skill group an aspected magician has access to.')
}

export function describeMentorSpirit(id: string): string {
  return lookup(MENTOR_SPIRIT_DESCRIPTIONS, id, 'A mentor spirit offering narrow bonuses tied to its themes.')
}

export function describeAdeptPower(id: string): string {
  return lookup(ADEPT_POWER_DESCRIPTIONS, id, 'An adept power purchased with Power Points.')
}

export function describeRitual(id: string): string {
  return lookup(RITUAL_DESCRIPTIONS, id, 'A group ritual built on an underlying spell.')
}

export function describeComplexForm(id: string): string {
  return lookup(COMPLEX_FORM_DESCRIPTIONS, id, 'A technomancer complex form threaded live from Resonance.')
}

export function describeSpell(spell: { id: string; category: string; type: string }): string {
  const specific = SPELL_DESCRIPTIONS[spell.id]
  if (specific) return specific
  const categoryText = SPELL_CATEGORY_DESCRIPTIONS[spell.category] ?? 'A spell with an effect defined by its category.'
  const typeText = SPELL_TYPE_DESCRIPTIONS[spell.type] ?? ''
  return typeText ? `${categoryText} ${typeText}` : categoryText
}

export function describeSkillDomain(domain: string): string {
  return lookup(SKILL_DOMAIN_DESCRIPTIONS, domain, 'A skill used to resolve related tests.')
}

export function describeAugmentationCategory(categoryId: string): string {
  return lookup(AUGMENTATION_CATEGORY_DESCRIPTIONS, categoryId, 'A cyberware or bioware augmentation.')
}

export function describeAugmentation(id: string, categoryId: string): string {
  return AUGMENTATION_DESCRIPTIONS[id] ?? describeAugmentationCategory(categoryId)
}

export function describeResourceCategory(groupKey: string): string {
  return lookup(RESOURCE_CATEGORY_DESCRIPTIONS, groupKey, 'Gear available for purchase during creation.')
}

export function describeResourceItem(id: string, groupKey: string): string {
  return GEAR_DESCRIPTIONS[id] ?? WEAPON_DESCRIPTIONS[id] ?? ARMOR_DESCRIPTIONS[id] ?? VEHICLE_DESCRIPTIONS[id] ?? CYBERDECK_DESCRIPTIONS[id] ?? describeResourceCategory(groupKey)
}
